parameters.functionCode:
// Prepare projects data for AI analysis
const projects = $input.all()[0]?.json || [];

// Format projects for AI analysis
const projectsText = projects.map(p => 
  `Project: ${p.title}
` +
  `Stage: ${p.stage}
` +
  `Score: ${p.score} (${p.color_code})
` +
  `Areas: ${p.affected_areas?.join(', ') || 'None'}
` +
  `Content: ${p.content?.substring(0, 200) || 'No description'}
` +
  `---
`
).join('\n');

return { projects_text: projectsText, projects_count: projects.length };

// Parse AI response and create opportunity records
const aiResponse = $input.all()[0]?.json?.response || '[]';
let opportunities = [];

try {
  opportunities = JSON.parse(aiResponse);
} catch (e) {
  console.error('Failed to parse AI response:', e);
  opportunities = [];
}

// Validate and enrich opportunities
const validOpportunities = opportunities.filter(opp => 
  opp.type && opp.confidence && opp.description
).map(opp => ({
  ...opp,
  confidence_score: Math.max(0, Math.min(1, opp.confidence)),
  identified_at: new Date().toISOString(),
  status: 'active'
}));

return validOpportunities;

// Check for incomplete projects that could be building blocks
// This is a fallback analysis if AI fails
const projects = $input.all()[0]?.json || [];
const opportunities = [];

projects.forEach(project => {
  // Building block detection
  if (project.stage === 'projects' && 
      project.affected_areas && 
      project.affected_areas.length >= 2 &&
      project.score >= 7) {
    opportunities.push({
      item_id: project.id,
      type: 'building_block',
      description: `High-impact project affecting ${project.affected_areas.length} areas could serve as foundation for other initiatives`,
      confidence_score: 0.8,
      affected_areas: project.affected_areas,
      potential_impact: 'Could accelerate multiple related projects',
      identified_at: new Date().toISOString(),
      status: 'active'
    });
  }

  // Near completion detection
  if (project.content && 
      (project.content.toLowerCase().includes('90%') || 
       project.content.toLowerCase().includes('almost done') ||
       project.content.toLowerCase().includes('final steps'))) {
    opportunities.push({
      item_id: project.id,
      type: 'near_completion',
      description: 'Project appears close to completion and could unlock other initiatives',
      confidence_score: 0.7,
      affected_areas: project.affected_areas || [],
      potential_impact: 'Completing this could unblock dependent work',
      identified_at: new Date().toISOString(),
      status: 'active'
    });
  }
});

return opportunities;

// Prepare strategic opportunities summary for Slack
const opportunities = $input.all();
const summary = {
  total_opportunities: opportunities.length,
  by_type: {},
  high_confidence: opportunities.filter(o => o.confidence_score >= 0.8).length,
  opportunities_list: opportunities.map(o => 
    `• *${o.title}* (${o.opportunity_type}) - ${o.description.substring(0, 100)}...`
  ).join('\n')
};

// Count by type
opportunities.forEach(o => {
  summary.by_type[o.opportunity_type] = (summary.by_type[o.opportunity_type] || 0) + 1;
});

return summary;

